const quotes_by_mint = new Map<string, (typeof QUOTE_MINTS)[Quote]>(
    Object.values(QUOTE_MINTS).map((quote) => [quote.mint.toBase58(), quote])
);
const quotes_by_ticker = new Map(Object.entries(QUOTE_MINTS).map(([ticker, quote]) => [ticker.toLowerCase(), quote]));
const quote_names_by_mint = new Map<string, string>(
    Object.entries(QUOTE_MINTS).map(([ticker, quote]) => [quote.mint.toBase58(), ticker])
);

export function get_quote_by_mint(mint: PublicKey | string) {
    return quotes_by_mint.get(typeof mint === 'string' ? mint : mint.toBase58());
}

export function get_quote_name_by_mint(mint: PublicKey | string) {
    return quote_names_by_mint.get(typeof mint === 'string' ? mint : mint.toBase58());
}

export function get_quote_by_ticker(ticker: string) {
    return quotes_by_ticker.get(ticker.toLowerCase());
}

export function is_quote(value: string): value is Quote {
    return Object.values(Quote)
        .map((s) => s.toLowerCase())
        .includes(value.toLowerCase() as Quote);
}
